def search(a, x):
    lo, hi = 0, len(a) - 1
    probes = []
    while lo <= hi:
        mid = (lo + hi) // 2
        probes.append(a[mid])
        if a[mid] == x:
            return probes
        elif a[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return probes

