leaves = {"E": (4, 9), "F": (7, 2), "G": (6, 1), "H": (8, 3), "I": (5, 10), "J": (11, 0)}
tree = {"A": ("max", ["B", "C", "D"]), "B": ("min", ["E", "F"]), "C": ("min", ["G", "H"]), "D": ("min", ["I", "J"])}
def value(node):
    if node in leaves:                       # MAX node over its two terminal utilities
        return max(leaves[node])
    kind, kids = tree[node]
    vals = [value(k) for k in kids]
    return max(vals) if kind == "max" else min(vals)
